			this._logService.error(err, `[Copilot:${this._sessionId}] Failed to write sandbox policy`);
			throw err;
		}
		return {
			kind: 'link',
			resource,
			label: localize('copilotSlashCommand.openSandboxPolicy', "Open Sandbox Policy"),
			preview: true,
		};
	}
}

